use vstd::prelude::*;

verus! {

    // A Hermite E‐polynomial is represented by
    //  - fixed domain bounds [-1.0, 1.0],
    //  - fixed window bounds [-1.0, 1.0],
    //  - and a coefficient vector `coef`.
    //
    // We require that the constructor preserves exactly the input coefficients,
    // and that the lengths agree, and that the bounds are set correctly.

    #[verifier(publish)]
    struct HermiteEPoly {
        domain_start: f32,
        domain_end:   f32,
        window_start: f32,
        window_end:   f32,
        coef:         Vec<f32>,
    }

    impl HermiteEPoly {
        // (Optionally one could add a spec method to observe invariants,
        //  but for this simple builder we state them in the constructor.)
    }

    // Construct a Hermite E‐polynomial from the given coefficients.
    // Ensures that
    //   • domain = [-1.0, 1.0]
    //   • window = [-1.0, 1.0]
    //   • the output coefficient vector has exactly the same length
    //     and the same entries as the input.
    fn hermite_e(coef: Vec<f32>) -> (result: HermiteEPoly)
        ensures
            // domain bounds
            result.domain_start == -1.0,
            result.domain_end   ==  1.0,
            // window bounds
            result.window_start == -1.0,
            result.window_end   ==  1.0,
            // same length
            result.coef.len() == coef.len(),
            // same entries
            forall |i: usize|
                i < coef.len() ==>
                result.coef[i] == coef[i],
    {
        HermiteEPoly {
            domain_start: -1.0,
            domain_end:   1.0,
            window_start: -1.0,
            window_end:   1.0,
            coef,
        }
    }
}

fn main() {
    // Example usage:
    let v = vec![0.0f32, 1.0, -2.5];
    let p = hermite_e(v.clone());
    // We know by spec that p.coef == v, and bounds are [-1,1].
    assert(p.coef.len() == 3);
    assert(p.coef[0] == 0.0);
    assert(p.domain_start == -1.0 && p.domain_end == 1.0);
}